export function translate(source: string, language: UiLanguage = "en", values: Record<string, string | number> = {}): string {
  const found = catalog[source];
  const reporting = reportingCatalog[source];
  let output = language === "en"
    ? source
    : language === "ar"
      ? (arabicCatalog[source] ?? arabicReportingCatalog[source] ?? arabicOverviewCatalog[source] ?? arabicAppCatalog[source] ?? arabicToolCatalog[source] ?? arabicDashboardCatalog[source] ?? arabicPublicPageCatalog[source] ?? arabicAdminCatalog[source] ?? source)
      : (found?.[localeIndex[language]] ?? reporting?.[localeIndex[language]] ?? appCatalog[source]?.[localeIndex[language]] ?? toolDashboardCatalog[source]?.[localeIndex[language]] ?? publicPageCatalog[source]?.[localeIndex[language]] ?? adminCatalog[source]?.[localeIndex[language]] ?? source);
  for (const [key, value] of Object.entries(values)) output = output.replaceAll(`{${key}}`, String(value));
  return output;
}

export function useI18n() {
  const { prefs } = usePrefs();
  const language: UiLanguage = UI_LANGUAGES.some((item) => item.code === prefs.uiLanguage)
    ? (prefs.uiLanguage as UiLanguage)
    : "en";
  return { language, t: (source: string, values?: Record<string, string | number>) => translate(source, language, values) };
}
